import { writeDb } from '../../db/write-pool.js';
import { orders } from './schema.js';

/** A second writer for orders — convenient, and exactly what the rule forbids. */
export async function bulkInsert(rows: { id: string; customerId: string; totalCents: number }[]): Promise<void> {
  await writeDb.insert(orders).values(rows);
}
